"""Comprehensive EPUB QA checker - content, structure, and compatibility."""
import zipfile, os, re, sys
from pathlib import Path
from xml.etree import ElementTree as ET

PACKAGES_DIR = Path("/home/bob/books/publishing_output/packages")

def check_epub(epub_path):
    """Run full QA check on an EPUB file."""
    book_name = epub_path.stem
    print(f"\n{'='*60}")
    print(f"📖 QA CHECK: {book_name}")
    print(f"{'='*60}")

    issues = []
    passes = []

    # Read EPUB
    if not epub_path.exists():
        issues.append(("FATAL", "File not found"))
        return book_name, issues, passes

    file_size_kb = os.path.getsize(epub_path) // 1024
    passes.append(f"File size: {file_size_kb} KB")
    if file_size_kb < 100:
        issues.append(("WARN", f"Very small EPUB ({file_size_kb} KB) - may be missing content"))

    try:
        zf = zipfile.ZipFile(epub_path, 'r')
    except zipfile.BadZipFile:
        issues.append(("FATAL", "Not a valid ZIP file"))
        return book_name, issues, passes

    namelist = zf.namelist()

    # 1. CHECK: mimetype first, uncompressed
    if 'mimetype' not in namelist:
        issues.append(("FAIL", "Missing mimetype file"))
    else:
        info = zf.getinfo('mimetype')
        if info.compress_type != zipfile.ZIP_STORED:
            issues.append(("WARN", "mimetype should be stored (uncompressed)"))
        else:
            passes.append("mimetype: stored uncompressed ✓")

        # Check mimetype is first entry
        if namelist.index('mimetype') != 0:
            issues.append(("WARN", "mimetype should be first entry in ZIP"))
        else:
            passes.append("mimetype: first entry ✓")

        # Check content
        mime_content = zf.read('mimetype').decode('utf-8').strip()
        if mime_content != 'application/epub+xml':
            issues.append(("FAIL", f"mimetype content wrong: '{mime_content}'"))
        else:
            passes.append("mimetype: application/epub+xml ✓")

    # 2. CHECK: Required directories/files
    checks = [
        'META-INF/container.xml',
        'OEBPS/content.opf',
    ]

    for req in checks:
        if req not in namelist:
            issues.append(("FAIL", f"Missing required file: {req}"))
        else:
            passes.append(f"Required file: {req} ✓")

    # 3. CHECK: container.xml
    if 'META-INF/container.xml' in namelist:
        try:
            cont = zf.read('META-INF/container.xml').decode('utf-8')
            if 'OEBPS/content.opf' in cont:
                passes.append("container.xml: points to content.opf ✓")
            else:
                issues.append(("FAIL", "container.xml doesn't reference content.opf"))
        except:
            issues.append(("FAIL", "container.xml unreadable"))

    # 4. CHECK: content.opf 
    if 'OEBPS/content.opf' in namelist:
        try:
            opf = zf.read('OEBPS/content.opf').decode('utf-8')

            # Metadata
            for field in ['<dc:title>', '<dc:creator>', '<dc:language>', '<dc:identifier']:
                if field in opf:
                    passes.append(f"OPF metadata: {field} ✓")
                else:
                    issues.append(("FAIL", f"OPF missing: {field}"))

            # Modified timestamp (required for EPUB 3)
            if 'dcterms:modified' in opf:
                passes.append("OPF: dcterms:modified timestamp ✓")
            else:
                issues.append(("WARN", "OPF missing dcterms:modified timestamp"))

            # Cover image reference
            if 'properties="cover-image"' in opf:
                passes.append("OPF: cover-image property ✓")
            else:
                issues.append(("WARN", "OPF missing cover-image property"))

            # Manifest items
            manifest_items = re.findall(r'<item\s+id="([^"]+)"\s+href="([^"]+)"', opf)
            manifest_count = len(manifest_items)
            passes.append(f"OPF manifest: {manifest_count} items ✓")

            # Check nav is in manifest
            nav_in_manifest = any(href == 'nav.xhtml' for _, href in manifest_items)
            if nav_in_manifest:
                passes.append("OPF: nav.xhtml in manifest ✓")
            else:
                issues.append(("FAIL", "nav.xhtml not in manifest"))

            # Spine items
            spine_items = re.findall(r'<itemref\s+idref="([^"]+)"', opf)
            passes.append(f"OPF spine: {len(spine_items)} itemrefs ✓")

            # Check spine doesn't contain nav or ncx
            for item in spine_items:
                # Find the matching manifest item's href
                for id_, href in manifest_items:
                    if id_ == item:
                        if href == 'nav.xhtml':
                            issues.append(("FAIL", "nav.xhtml should NOT be in spine"))
                        break

            # Guide items
            if '<guide>' in opf:
                for ref_type in ['cover', 'toc', 'text']:
                    if f'type="{ref_type}"' in opf:
                        passes.append(f"OPF guide: {ref_type} ✓")
                    else:
                        issues.append(("WARN", f"OPF guide missing: {ref_type}"))
            else:
                issues.append(("WARN", "OPF missing <guide> section"))

        except Exception as e:
            issues.append(("FAIL", f"content.opf error: {e}"))

    # 5. CHECK: Nav TOC
    if 'OEBPS/nav.xhtml' in namelist:
        try:
            nav = zf.read('OEBPS/nav.xhtml').decode('utf-8')
            if 'epub:type="toc"' in nav:
                passes.append("nav.xhtml: epub:type=toc ✓")
            else:
                issues.append(("FAIL", "nav.xhtml missing epub:type=toc"))

            # Count TOC entries
            toc_links = re.findall(r'<a href="([^"]+)">', nav)
            passes.append(f"nav.xhtml: {len(toc_links)} TOC entries ✓")

            # All nav links should resolve to files in EPUB
            for link in toc_links:
                link_path = f"OEBPS/{link}"
                if link_path not in namelist:
                    issues.append(("WARN", f"nav link target not found: {link}"))

        except Exception as e:
            issues.append(("FAIL", f"nav.xhtml error: {e}"))
    else:
        issues.append(("FAIL", "Missing nav.xhtml"))

    # 6. CHECK: NCX
    if 'OEBPS/toc.ncx' in namelist:
        ncx = zf.read('OEBPS/toc.ncx').decode('utf-8')
        ncx_points = ncx.count('<navPoint')
        passes.append(f"toc.ncx: {ncx_points} navPoints ✓")
    else:
        issues.append(("WARN", "Missing toc.ncx (EPUB 2 backward compat)"))

    # 7. CHECK: XHTML files
    xhtml_files = [n for n in namelist if n.endswith('.xhtml') and n.startswith('OEBPS/')]
    passes.append(f"XHTML files: {len(xhtml_files)} ✓")

    # Expected files
    expected_xhtml = ['cover.xhtml', 'title.xhtml', 'copyright.xhtml', 'toc.xhtml', 'nav.xhtml', 'about.xhtml', 'series.xhtml']
    for exp in expected_xhtml:
        if f'OEBPS/{exp}' in namelist:
            passes.append(f"  {exp} ✓")
        else:
            issues.append(("WARN", f"Missing expected file: {exp}"))

    # Check at least 5 chapter files
    chapter_files = [n for n in xhtml_files if re.match(r'OEBPS/ch\d{3}\.xhtml$', n)]
    if len(chapter_files) >= 5:
        passes.append(f"Chapters: {len(chapter_files)} ✓")
    else:
        issues.append(("WARN", f"Only {len(chapter_files)} chapter files (expected 5+)"))

    # 8. CHECK: XHTML content (spot check first chapter)
    if chapter_files:
        try:
            ch1 = zf.read(chapter_files[0]).decode('utf-8')
            if '<h2>' in ch1 or '<h1>' in ch1:
                passes.append(f"{chapter_files[0]}: has heading ✓")
            else:
                issues.append(("WARN", f"{chapter_files[0]}: no heading found"))
            if ch1.strip().endswith('</html>'):
                passes.append(f"{chapter_files[0]}: well-formed ✓")
        except:
            issues.append(("WARN", f"Could not read {chapter_files[0]}"))

    # 9. CHECK: Images
    image_files = [n for n in namelist if n.startswith('OEBPS/images/')]
    if image_files:
        passes.append(f"Images: {len(image_files)} ✓")
        for img in image_files:
            size = len(zf.read(img))
            if size > 10000:
                passes.append(f"  {Path(img).name}: {size//1024}KB ✓")
            else:
                issues.append(("WARN", f"  {Path(img).name}: only {size//1024}KB"))

    # 10. CHECK: No scripts
    for name in namelist:
        if name.endswith('.xhtml'):
            content = zf.read(name).decode('utf-8', errors='ignore')
            if '<script' in content.lower():
                issues.append(("FAIL", f"Script tag found in: {name}"))

    # 11. CHECK: No duplicate IDs
    all_ids = []
    for name in namelist:
        if name.endswith('.xhtml'):
            content = zf.read(name).decode('utf-8', errors='ignore')
            ids = re.findall(r'id="([^"]*)"', content)
            all_ids.extend(ids)
    id_counts = {}
    for id_ in all_ids:
        id_counts[id_] = id_counts.get(id_, 0) + 1
    dupes = {k: v for k, v in id_counts.items() if v > 1}
    if dupes:
        for id_, count in dupes.items():
            issues.append(("WARN", f"Duplicate ID '{id_}' found {count} times"))

    zf.close()

    # Print results
    if not issues:
        print(f"\n✅ ALL CHECKS PASS")
    else:
        print(f"\n📋 ISSUES FOUND:")
        for severity, msg in issues:
            icon = "❌" if severity == "FAIL" else "⚠️" if severity == "WARN" else "🔴"
            print(f"  {icon} [{severity}] {msg}")

    print(f"\n✅ PASSED ({len(passes)} checks):")
    for p in passes:
        print(f"  ✓ {p}")

    if issues:
        print(f"\n⚠️  ISSUES ({len(issues)} total):")
        fails = [i for i in issues if i[0] == "FAIL"]
        warns = [i for i in issues if i[0] == "WARN"]
        if fails:
            print(f"  ❌ {len(fails)} FAIL")
        if warns:
            print(f"  ⚠️  {len(warns)} WARNINGS")

    return book_name, issues, passes

def main():
    print("="*60)
    print("EPUB QA CHECK - ALL BOOKS")
    print("="*60)

    epub_files = sorted(PACKAGES_DIR.glob("*.epub"))

    if not epub_files:
        print(f"No .epub files found in {PACKAGES_DIR}")
        return

    all_results = []
    total_fails = 0
    total_warns = 0

    for epub in epub_files:
        name, issues, passes = check_epub(epub)
        all_results.append((name, issues, passes))
        fails = len([i for i in issues if i[0] == "FAIL"])
        warns = len([i for i in issues if i[0] == "WARN"])
        total_fails += fails
        total_warns += warns

    print(f"\n{'='*60}")
    print("SUMMARY")
    print(f"{'='*60}")

    for name, issues, passes in all_results:
        fails = len([i for i in issues if i[0] == "FAIL"])
        warns = len([i for i in issues if i[0] == "WARN"])
        status = "✅ PASS" if not fails else "❌ FAIL"
        print(f"  {status} {name}: {len(passes)} passed, {fails} fails, {warns} warnings")

    print(f"\nTotal: {total_fails} failures, {total_warns} warnings across {len(epub_files)} EPUBs")

if __name__ == "__main__":
    main()
